int main(){const auto profile=read(PROFILE_PATH);const auto bisect=read(BISECT_PATH);auto has=[](const std::string& text,const char* value){return text.find(value)!=std::string::npos;};return has(profile,"static-analysis: warnings-as-errors")&&has(profile,"baseline-comparisons: four")&&has(profile,"scaled-comparisons: nine")&&has(profile,"hotspot: linear-scan")&&has(bisect,"first-bad: quadratic-regression")&&has(bisect,"command: git bisect run")?0:1;}

