#include <iostream>
#include <vector>
int main(){int n{};std::cin>>n;std::vector<int> values(static_cast<std::size_t>(n));for(int& value:values)std::cin>>value;if(values.empty()){std::cout<<"min=none comparisons=0\n";return 0;}int minimum=values.front();std::size_t comparisons=0;for(std::size_t index=1;index<values.size();++index){++comparisons;if(values[index]<minimum)minimum=values[index];}std::cout<<"min="<<minimum<<" comparisons="<<comparisons<<"\n";}

